const arg = process.argv.indexOf('--today');
const now = arg > 0 ? new Date(process.argv[arg + 1] + 'T23:59:59Z') : new Date();
const weekAgo = new Date(now - 7 * 864e5);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
