console.log(JSON.stringify(summary, null, 1));
if (out) {
  const ids = new Map(); const comm = best.lab.map((l, v) => (adj[v].length ? (ids.has(l) ? ids.get(l) : (ids.set(l, ids.size), ids.size - 1)) : -1));
