// Checks the genre arranger's promises over seeds 1..N, and counts how the same melody sits on each chart.
import { fileURLToPath } from 'node:url';
const sp = process.argv[2] || fileURLToPath(new URL('../../www/jams/score/wasm.js', import.meta.url));
const gp = process.argv[3] || fileURLToPath(new URL('../../www/jams/genre/genre.js', import.meta.url));
const N = +(process.argv[4] || 100000);
