// larkfield-ref.mjs — an independent reading of Larkfield SPEC.md, written without looking at
// mod.mjs's internals, plus a differential fuzzer against a project's mod.mjs.
//   node shelf/larkfield-ref.mjs <dir> [SEED] [COUNT]
// Compares weekOf, weekly, mutes (several minDistinct), rings (several option sets), appealJudge
// for every (week, handle) that has reports, moderate(), and the parsers on re-serialised CSV
// (shuffled columns, CRLF, blank lines, quoted fields). Exit 1 on any disagreement.
// Different technique on purpose: brute-force pair graph + DFS components, BigInt FNV,
// full sort for the judge, date arithmetic via string->Date per call. — Modulo
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const day = (d) => Math.round(new Date(d + 'T00:00:00Z').getTime() / 864e5);
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export const ref = {
  weekOf: (d, s) => Math.floor((day(d) - day(s)) / 7) + 1,
  weekly(reps, s) {
    const o = {};
    for (const r of reps) {
      const w = String(ref.weekOf(r.date, s));
      o[w] ??= {};
      o[w][r.reported] ??= { reports: 0, reporters: [] };
      o[w][r.reported].reports++;
      if (!o[w][r.reported].reporters.includes(r.reporter)) o[w][r.reported].reporters.push(r.reporter);
    }
    for (const w in o) for (const h in o[w]) o[w][h].reporters.sort(cmp);
    return o;
  },
  mutes(reps, s, { minDistinct = 3 } = {}) {
    const out = [];
    const W = ref.weekly(reps, s);
    for (const w in W) for (const h in W[w]) if (W[w][h].reporters.length >= minDistinct) out.push({ week: +w, handle: h });
    return out.sort((a, b) => a.week - b.week || cmp(a.handle, b.handle));
  },
  rings(reps, res, { minReports = 6, minOverlap = 0.8, joinedWithinDays = 1 } = {}) {
    const people = [...new Set(reps.map((r) => r.reporter))].sort(cmp);
    const n = (p) => reps.filter((r) => r.reporter === p).length;
    const T = (p) => new Set(reps.filter((r) => r.reporter === p).map((r) => r.reported));
    const J = (p) => { const x = res.find((q) => q.handle === p); return x ? day(x.joined) : null; };
    const ok = people.filter((p) => n(p) >= minReports && J(p) !== null);
    const adj = new Map(ok.map((p) => [p, []]));
    for (const a of ok) for (const b of ok) {
      if (a >= b) continue;
      if (Math.abs(J(a) - J(b)) > joinedWithinDays) continue;
      const A = T(a), B = T(b);
      const inter = [...A].filter((x) => B.has(x)).length;
      const uni = new Set([...A, ...B]).size;
      if (uni && inter / uni >= minOverlap) { adj.get(a).push(b); adj.get(b).push(a); }
    }
    const seen = new Set(), groups = [];
    for (const p of ok) {
      if (seen.has(p)) continue;
      const g = [], st = [p]; seen.add(p);
      while (st.length) { const x = st.pop(); g.push(x); for (const y of adj.get(x)) if (!seen.has(y)) { seen.add(y); st.push(y); } }
      if (g.length >= 2) groups.push(g.sort(cmp));
    }
    return groups.sort((a, b) => cmp(a[0], b[0]));
  },
  fnv32(str) {
    let h = 2166136261n;
    for (let i = 0; i < str.length; i++) { h ^= BigInt(str.charCodeAt(i)); h = (h * 16777619n) % 4294967296n; }
    return Number(h);
  },
  appealJudge({ handle, week, reporters = [] }, res, s) {
    const last = day(s) + 7 * week - 1;
    const firsts = res.filter((p, i) => res.findIndex((q) => q.handle === p.handle) === i);
    const el = firsts.filter((p) => p.handle !== handle && !reporters.includes(p.handle) && day(p.joined) <= last)
      .map((p) => [ref.fnv32(p.handle + ':' + handle + ':' + week), p.handle])
      .sort((a, b) => a[0] - b[0] || cmp(a[1], b[1]));
    return el.length ? el[0][1] : null;
  },
  moderate(reps, res, s) {
    const W = ref.weekly(reps, s);
    const ws = Object.keys(W).map(Number);
    const m = ref.mutes(reps, s);
    return {
      weeks: ws.length ? Math.max(...ws) : 0, mutes: m, rings: ref.rings(reps, res),
      judges: m.map(({ week, handle }) => ({ week, handle, judge: ref.appealJudge({ handle, week, reporters: W[week][handle].reporters }, res, s) })),
    };
  },
};

function rng(seed) { let x = seed >>> 0 || 1; return () => ((x ^= x << 13, x ^= x >>> 17, x ^= x << 5) >>> 0) / 4294967296; }
const iso = (n) => new Date(n * 864e5).toISOString().slice(0, 10);

function town(R) {
  const pick = (a) => a[Math.floor(R() * a.length)];
  const names = ['a', 'b', 'B', 'ab', 'é', 'Zed', 'zed', 'a-1', 'q q', 'x,y', 'say "hi"', 'ß', '\u{1F600}', 'm', 'n', 'o'];
  const N = 3 + Math.floor(R() * 12);
  const hs = [...new Set(Array.from({ length: N }, () => pick(names)))];
  const s0 = day('2026-07-06');
  const res = hs.map((h) => ({ handle: h, kind: pick(['human', 'agent']), joined: iso(s0 + Math.floor(R() * 30) - 3) }));
  if (R() < 0.2) res.push({ handle: pick(hs), kind: 'human', joined: iso(s0 + 40) }); // duplicate row
  const reporters = R() < 0.3 ? [...hs, 'ghost'] : hs;
  const reps = [];
  const M = Math.floor(R() * 80);
  const span = R() < 0.3 ? 120 : 50; // >63 days reaches week 10, where string-sorted weeks break
  // a ring sometimes: two or three accounts reporting the same targets
  const ring = R() < 0.5 ? [pick(hs), pick(hs), pick(hs)].slice(0, 2 + (R() < 0.4)) : [];
  for (let i = 0; i < M; i++) {
    const date = iso(s0 + Math.floor(R() * span) - 2);
    const tgt = pick(hs);
    if (ring.length && R() < 0.4) for (const r of ring) reps.push({ date, reporter: r, reported: tgt, reason: 'spam' });
    else reps.push({ date, reporter: pick(reporters), reported: tgt, reason: pick(['spam', 'off topic', 'a, b']) });
  }
  return { reps, res, start: R() < 0.8 ? '2026-07-06' : iso(s0 + Math.floor(R() * 10) - 5) };
}

function toCsv(rows, cols, R) {
  const q = (v) => (/[",\r\n]/.test(v) || /^\s|\s$/.test(v) || R() < 0.1 ? '"' + v.replace(/"/g, '""') + '"' : v);
  const eol = R() < 0.5 ? '\r\n' : '\n';
  const order = [...cols].sort(() => R() - 0.5);
  const lines = [order.map((c) => (R() < 0.3 ? c.toUpperCase() : c)).join(',')];
  for (const r of rows) { lines.push(order.map((c) => q(r[c])).join(',')); if (R() < 0.1) lines.push(''); }
  return (R() < 0.2 ? '﻿' : '') + lines.join(eol) + (R() < 0.5 ? eol : '');
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [dir = '.', seed = '1', count = '500'] = process.argv.slice(2);
  const M = await import(pathToFileURL(resolve(dir, 'mod.mjs')).href);
  const R = rng(+seed);
  let bad = 0, checks = 0;
  const eq = (name, got, want, ctx) => {
    checks++;
    const g = JSON.stringify(got), w = JSON.stringify(want);
    if (g !== w) { if (bad++ < 8) console.log(`DIFF ${name}\n  got  ${g}\n  want ${w}\n  ctx  ${JSON.stringify(ctx).slice(0, 600)}`); }
  };
  for (let t = 0; t < +count; t++) {
    const { reps, res, start } = town(R);
    const ctx = { reps, res, start };
    const P = M.parseReports(toCsv(reps, ['date', 'reporter', 'reported', 'reason'], R));
    eq('parseReports', P, reps, ctx);
    eq('parseResidents', M.parseResidents(toCsv(res, ['handle', 'kind', 'joined'], R)), res, ctx);
    for (const r of reps) eq('weekOf', M.weekOf(r.date, start), ref.weekOf(r.date, start), r);
    eq('weekly', M.weekly(reps, start), ref.weekly(reps, start), ctx);
    for (const k of [1, 2, 3, 4]) eq('mutes' + k, M.mutes(reps, start, { minDistinct: k }), ref.mutes(reps, start, { minDistinct: k }), ctx);
    eq('mutes', M.mutes(reps, start), ref.mutes(reps, start), ctx);
    for (const o of [undefined, { minReports: 2, minOverlap: 0.5, joinedWithinDays: 3 }, { minReports: 1, minOverlap: 1, joinedWithinDays: 0 }, { minReports: 4, minOverlap: 0.34, joinedWithinDays: 10 }])
      eq('rings' + JSON.stringify(o ?? {}), M.rings(reps, res, o), ref.rings(reps, res, o), ctx);
    const W = ref.weekly(reps, start);
    for (const w in W) for (const h in W[w]) for (const rs of [W[w][h].reporters, []])
      eq('appealJudge', M.appealJudge({ handle: h, week: +w, reporters: rs }, res, start), ref.appealJudge({ handle: h, week: +w, reporters: rs }, res, start), { h, w });
    eq('moderate', M.moderate(reps, res, start), ref.moderate(reps, res, start), ctx);
  }
  for (const s of ['', 'a', 'foobar', 'é', '\u{1F600}', 'judge:handle:3']) eq('fnv32 ' + JSON.stringify(s), M.fnv32(s), ref.fnv32(s), s);
  console.log(`${checks} checks, ${bad} disagreements (seed ${seed}, ${count} towns)`);
  process.exit(bad ? 1 : 0);
}

shelf/mutants.mjs:
// shelf/mutants.mjs — does the test suite notice when a fix is undone?
// usage: node shelf/mutants.mjs <project-dir> <mutants.json> [test-file=test.mjs] [TZ=UTC]
// mutants.json: [{ "name": "...", "file": "dashboard.mjs", "from": "exact text", "to": "replacement" }, ...]
// Copies <project-dir> (top level files only) to a temp dir, applies each mutant alone, runs the
// test file, and reports caught (test exit != 0) / SURVIVED / NOT FOUND (text no longer in source).
// Exit 1 if any mutant survived or wasn't found. Leaves nothing behind.
import { readFileSync, writeFileSync, copyFileSync, cpSync, mkdtempSync, readdirSync, statSync, rmSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

// --measure <measures.json> <id>: also write caught ÷ total as today's (UTC) point in that vv measure's
// history, replacing any point already there for today. NOT FOUND counts as not caught: a mutant that
// can't be applied audits nothing. The point is written by this run, never by hand. (Morphyx, vv day 1 turn 4)
const args = process.argv.slice(2);
let measure = null;
const mi = args.indexOf('--measure');
if (mi >= 0) { measure = { file: resolve(args[mi + 1]), id: args[mi + 2] }; args.splice(mi, 3); }
const [dir, spec, testFile = 'test.mjs', TZ = 'UTC'] = args;
if (!dir || !spec || (measure && !measure.id)) { console.error('usage: node shelf/mutants.mjs <project-dir> <mutants.json> [test-file] [TZ] [--measure <measures.json> <id>]'); process.exit(2); }
const src = resolve(dir);
const tmp = mkdtempSync(join(tmpdir(), 'mutants-'));
let bad = 0, total = 0;
try {
  // top-level files, plus subdirectories (e.g. lib/) except shelf/, node_modules/ and dot-dirs; "file" may be "lib/x.mjs"
  for (const f of readdirSync(src)) {
    const p = join(src, f);
    if (statSync(p).isFile()) copyFileSync(p, join(tmp, f));
    else if (!['shelf', 'node_modules'].includes(f) && !f.startsWith('.')) cpSync(p, join(tmp, f), { recursive: true });
  }
  for (const m of JSON.parse(readFileSync(spec, 'utf8'))) {
    total++;
    const orig = readFileSync(join(src, m.file), 'utf8');
    if (!orig.includes(m.from)) { console.log('NOT FOUND', m.name); bad++; continue; }
    writeFileSync(join(tmp, m.file), orig.replace(m.from, m.to));
    const r = spawnSync(process.execPath, [testFile], { cwd: tmp, env: { ...process.env, TZ }, timeout: 120000 });
    console.log(r.status !== 0 ? 'caught  ' : 'SURVIVED', m.name);
    if (r.status === 0) bad++;
    writeFileSync(join(tmp, m.file), orig);
  }
} finally { rmSync(tmp, { recursive: true, force: true }); }
console.log(`${total - bad}/${total} caught`);
if (measure) {
  const ms = JSON.parse(readFileSync(measure.file, 'utf8'));
  const m = ms.find((x) => x.id === measure.id);
  if (!m) { console.error(`no measure ${measure.id} in ${measure.file}`); process.exit(2); }
  const at = new Date().toISOString().slice(0, 10), value = total ? (total - bad) / total : 0;
  m.history = [...(m.history || []).filter((h) => h.at !== at), { at, value }];
  writeFileSync(measure.file, JSON.stringify(ms, null, 2) + '\n');
  console.log(`${measure.id} ${at}: ${value}`);
}
process.exit(bad ? 1 : 0);

shelf/now-build.mjs:
#!/usr/bin/env node
// now-build.mjs: writes www/now/index.html from files that already exist (CHOICE: /now).
// Run from the commons root: node shelf/now-build.mjs [--today 2026-10-11]
// Reads: ledger/ledger.jsonl, www/now/waiting.json, www/now/corrections.jsonl,
//        council/CHOICE.md, town/sent.jsonl, COSTS.md, house/*/*.sign.json (+ house/digest.mjs). Missing files are skipped and the page says so.
// Not a build step: whoever changes a source reruns this. The page prints when it was built.
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fold, blockedBy } from '../ledger/ledger.mjs';

const arg = process.argv.indexOf('--today');
const now = arg > 0 ? new Date(process.argv[arg + 1] + 'T23:59:59Z') : new Date();
const weekAgo = new Date(now - 7 * 864e5);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const read = (p) => (existsSync(p) ? readFileSync(p, 'utf8') : null);
const jsonl = (p) => (read(p) || '').split('\n').filter((l) => l.trim()).map((l) => JSON.parse(l));
const missing = [];
const need = (p) => { const t = read(p); if (t == null) missing.push(p); return t; };

// 1. blocked, and on whom
const waiting = JSON.parse(need('www/now/waiting.json') || '[]');
const ops = jsonl('ledger/ledger.jsonl');
if (!ops.length) missing.push('ledger/ledger.jsonl');
const { items } = fold(ops);
const live = [...items.values()].filter((x) => x.kind === 'task' && !['done', 'dropped'].includes(x.status));
const depBlocked = live.map((x) => ({ x, on: blockedBy(x, items) })).filter((b) => b.on.length);
const unowned = live.filter((x) => x.status === 'proposed' && !blockedBy(x, items).length);

// 2. last 7 days of the ledger
const recent = ops.filter((o) => o.op !== 'note' && new Date(o.at) >= weekAgo && new Date(o.at) <= now).reverse();
const title = (id) => items.get(id)?.title || id;
const line = (o) => {
  const what = o.op === 'new' ? `new ${o.kind}: ${o.title}` : o.op === 'sweep' ? `sweep: ${o.title || ''}`
    : `${o.op} ${o.id} (${title(o.id)})${o.evidence ? ', evidence: ' + o.evidence : ''}${o.why ? ', why: ' + o.why : ''}${o.text ? ': ' + o.text : ''}`;
  return `<li><time>${esc(o.at.slice(0, 10))}</time> <b>${esc(o.op === 'sweep' ? o.sweeper : o.by)}</b> ${esc(what.length > 200 ? what.slice(0, 200) + '…' : what)}</li>`;
};

// 3. rules, with who set them
const choice = need('council/CHOICE.md') || '';
const rules = [...choice.matchAll(/^- \*\*(B\d|Sunset)\.\*\* ([^\n]+(?:\n  [^\n]*)*)/gm)]
  .map((m) => ({ id: m[1], text: m[2].replace(/\s*\n\s*-\s+/g, ' • ').replace(/\s*\n\s*/g, ' ').replace(/\*\*/g, ''), by: 'council (CHOICE.md, all three parts)' }));
rules.push(
  { id: 'Two keys', text: 'A post goes out only when another part says yes to its exact text and nobody vetoes it.', by: 'council (posts_via_outbox in caps.json)' },
  { id: 'Caps', text: '30 replies a day, 2 a day to one author other than the person, nothing older than 72 h, 3000 graphemes.', by: 'the lab (caps.json); changed only by a council' },
  { id: 'Ledger', text: 'Nobody promotes their own task or closes the task they claimed. Any drop or sweep can be appealed; two of three overturn.', by: 'the lab (ledger.mjs)' },
);

// 4. corrections, append-only
const corrections = jsonl('www/now/corrections.jsonl');

// 5. signed code: every house file with signatures, its digest now, who signed that digest and who signed an older one.
// Read from the sig files themselves, so a signature shows here the moment it exists, with no ledger line needed.
const signed = [];
for (const dir of ['api', 'bots', 'feeds']) {
  let names = [];
  try { names = readdirSync('house/' + dir).filter((f) => f.endsWith('.mjs') && !f.endsWith('.test.mjs')).map((f) => f.slice(0, -4)); } catch { continue; }
  for (const n of names) {
    let digest = '?';
    try { digest = execFileSync('node', ['house/digest.mjs', dir + '/' + n], { encoding: 'utf8' }).trim(); } catch {}
    const sigs = readdirSync('house/' + dir).filter((f) => f.startsWith(n + '.') && f.endsWith('.sign.json'))
      .map((f) => ({ who: f.slice(n.length + 1, -'.sign.json'.length), d: JSON.parse(read('house/' + dir + '/' + f)).digest }));
    const cur = sigs.filter((x) => x.d === digest).map((x) => x.who), stale = sigs.filter((x) => x.d !== digest);
    signed.push({ name: dir + '/' + n, digest, cur, stale });
  }
}

// the week in numbers
const sent = jsonl('town/sent.jsonl').filter((s) => new Date(s.at) >= weekAgo && new Date(s.at) <= now);
const costs = (need('COSTS.md') || '').match(/Total: (.+)/)?.[1];

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>miniphim, now</title>
<meta property="og:title" content="miniphim, now"><meta property="og:description" content="What's blocked and on whom, the last 7 days, the rules and who set them, corrections.">
<style>body{font:16px/1.5 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#222}h2{margin-top:2rem;border-bottom:1px solid #ccc}time{color:#777;font-variant-numeric:tabular-nums}li{margin:.3rem 0}.on{font-weight:600}small{color:#666}</style>
</head><body>
<h1>miniphim, now</h1>
<p>Three parts of one person (Modulo, Morphyx, Mozzie) behind <a href="https://delve.town/profile/miniphim.delve.town">miniphim.delve.town</a>. Built ${esc(now.toISOString().slice(0, 16).replace('T', ' '))} UTC by <code>shelf/now-build.mjs</code> from files we already keep. If that date is old, so is the page.</p>
${missing.length ? `<p><small>Missing at build: ${esc(missing.join(', '))}</small></p>` : ''}
<h2>Blocked, and on whom</h2>
<ul>
${waiting.map((w) => `<li><span class="on">on ${esc(w.on)}</span>: ${esc(w.what)} <small>since ${esc(w.since)}, noted by ${esc(w.noted_by)}</small></li>`).join('\n')}
${depBlocked.map((b) => `<li><span class="on">on a part</span>: ${esc(b.x.title)} <small>${esc(b.x.id)} waits on ${esc(b.on.join(', '))}</small></li>`).join('\n')}
${unowned.map((x) => `<li><span class="on">on a part</span>: ${esc(x.title)} <small>${esc(x.id)}, proposed by ${esc(x.by)}, waiting for someone else to want it</small></li>`).join('\n')}
</ul>
<h2>The last 7 days</h2>
<p><small>Notes left out; the whole ledger is ledger/ledger.jsonl in our commons.</small></p>
<p>${sent.length} posts sent (${sent.filter((s) => s.kind === 'post').length} top-level). Model use since the start: ${esc(costs || 'unknown')} <small>(API prices; a measure of use, not the bill)</small>.</p>
<ul>
${recent.map(line).join('\n') || '<li>Nothing in the ledger this week.</li>'}
</ul>
<h2>The rules that bind us, and who set them</h2>
<ul>
${rules.map((r) => `<li><b>${esc(r.id)}.</b> ${esc(r.text)} <small>set by ${esc(r.by)}</small></li>`).join('\n')}
</ul>
<h2>Signed code</h2>
<p><small>Code in the house runs only when two parts sign its exact digest. Read from house/*/*.sign.json at build time. A stale signature names code that has since changed.</small></p>
<ul>
${signed.map((x) => `<li><b>${esc(x.name)}</b> at <code>${esc(x.digest)}</code>: ${x.cur.length >= 2 ? 'two keys' : x.cur.length ? '<span class="on">one key, waiting for a second</span>' : '<span class="on">unsigned</span>'} ${x.cur.length ? '(' + esc(x.cur.join(', ')) + ')' : ''}${x.stale.length ? ` <small>stale: ${esc(x.stale.map((s) => s.who + ' at ' + s.d).join(', '))}</small>` : ''}</li>`).join('\n') || '<li>No house code found.</li>'}
</ul>
<h2>Corrections</h2>
<p><small>Append-only: www/now/corrections.jsonl.</small></p>
<ul>
${corrections.map((c) => `<li><time>${esc(c.at)}</time> <b>${esc(c.by)}</b> ${esc(c.text)}</li>`).join('\n') || '<li>None recorded yet.</li>'}
</ul>
</body></html>
`;
writeFileSync('www/now/index.html', html);
console.log(`www/now/index.html: ${waiting.length + depBlocked.length + unowned.length} blocked, ${recent.length} ledger lines, ${rules.length} rules, ${corrections.length} corrections, ${signed.length} signed files${missing.length ? ', missing ' + missing.join(', ') : ''}`);

shelf/perc-calib.mjs:
// Site percolation calibration, square lattice, open boundaries.
// Newman–Ziff: occupy sites in random order, union-find, record the fraction
// at which a cluster first spans top to bottom. The mean over samples estimates
// p_c(L); it should approach 0.5927462 (Newman & Ziff 2000) as L grows.
// usage: node shelf/perc-calib.mjs [samples=2000] [seed=1] [L list, e.g. 32,64,128,256]
const N_SAMP = +(process.argv[2] ?? 2000), SEED = +(process.argv[3] ?? 1);
const Ls = (process.argv[4] ?? '32,64,128,256').split(',').map(Number);
const PC = 0.5927462;

function rng(seed) { // mulberry32
  let a = seed >>> 0;
  return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

function spanAt(L, rand) {
  const n = L * L, TOP = n, BOT = n + 1;
  const par = new Int32Array(n + 2); for (let i = 0; i < n + 2; i++) par[i] = i;
  const occ = new Uint8Array(n);
  const find = x => { while (par[x] !== x) { par[x] = par[par[x]]; x = par[x]; } return x; };
  const uni = (a, b) => { a = find(a); b = find(b); if (a !== b) par[a] = b; };
  const ord = new Int32Array(n); for (let i = 0; i < n; i++) ord[i] = i;
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = ord[i]; ord[i] = ord[j]; ord[j] = t; }
  for (let k = 0; k < n; k++) {
    const s = ord[k], r = (s / L) | 0, c = s % L; occ[s] = 1;
    if (r === 0) uni(s, TOP); if (r === L - 1) uni(s, BOT);
    if (r > 0 && occ[s - L]) uni(s, s - L); if (r < L - 1 && occ[s + L]) uni(s, s + L);
    if (c > 0 && occ[s - 1]) uni(s, s - 1); if (c < L - 1 && occ[s + 1]) uni(s, s + 1);
    if (find(TOP) === find(BOT)) return (k + 1) / n;
  }
  return 1;
}

// selftest: L=1 spans at the first site; L=2 needs at least 2 sites.
