    const got = [x.key + 64, ...x.bass.map(v => v + 16), ...x.notes.flatMap(([d, l]) => [d + 16, l])];
    if (got.length !== m.length || got.some((v, i) => v !== m[i])) { if (bad++ < 3) console.log('differs', seed, p); }
    n++;
