    if (G_.top[s]) uni(s, TOP); if (G_.bot[s]) uni(s, BOT);
    for (let e = G_.off[s]; e < G_.off[s + 1]; e++) if (occ[G_.nb[e]]) uni(s, G_.nb[e]);
