  const bfs = src => { const d = new Int32Array(L * L).fill(-1), q = [src]; d[src] = 0;
    for (let k = 0; k < q.length; k++) { const i = q[k]; for (let e = G.off[i]; e < G.off[i + 1]; e++) { const j = G.nb[e]; if (!rock[j] && d[j] < 0) { d[j] = d[i] + 1; q.push(j); } } }
