    ok(x === GOLD.maze && M.open === 49 * 49 * 2 - 1, `maze: a perfect maze has 2·49²−1 = 4801 open squares, pinned run: ${x}`); }
  // Voronoi: on a torus every cell's neighbours must be mutual and the mean degree exactly 6 (Euler). A dropped edge breaks both.
  const vstruct = g => { let asym = 0; for (let i = 0; i < g.N; i++) for (let e = g.off[i]; e < g.off[i + 1]; e++) { const j = g.nb[e]; let f = false;
      for (let k = g.off[j]; k < g.off[j + 1]; k++) if (g.nb[k] === i) f = true; if (!f) asym++; } return { asym, deg: g.nb.length / g.N }; };
  { const g = voronoi(30, rng(5), true), v = vstruct(g); ok(v.asym === 0 && Math.abs(v.deg - 6) < 1e-12, `vor torus 30²: ${v.asym} one-way links, mean degree ${v.deg}`);
    const nb = [], off = new Int32Array(g.N + 1); for (let i = 0; i < g.N; i++) { for (let e = g.off[i]; e < g.off[i + 1] - 1; e++) nb.push(g.nb[e]); off[i + 1] = nb.length; }
    const vm = vstruct({ N: g.N, off, nb }); ok(vm.asym > 0 && vm.deg < 5.5, `mutant: vor with each cell's last edge dropped has ${vm.asym} one-way links, degree ${vm.deg.toFixed(2)} (caught)`); }
  // hex6c is a cylinder: no side edges, so it spans early at finite L, by a gap that should shrink like L^-3/4 (x2.83 from 32 to 128).
  { const a = thresh('hex6c', 32, 400, 1), b = thresh('hex6c', 128, 150, 1), ga = a.m - 0.5, gb = b.m - 0.5, ratio = ga / gb;
    ok(ga < 0 && gb < 0 && ratio > 1.8 && ratio < 4.5, `hex6c cylinder: gap to 1/2 is ${ga.toFixed(4)} at L=32 and ${gb.toFixed(4)} at L=128, ratio ${ratio.toFixed(2)} (expect ~2.8): closing on 1/2`); }
  // mutant 1: Moore with one corner missing must miss 0.4073 by a mile, or the threshold check can't catch a wrong table
  LATTICES.mut = { offs: LATTICES.sq8.offs.slice(0, 7), pc: NaN };
  const mu = thresh('mut', 64, 300, 1); delete LATTICES.mut;
  ok((mu.m - 0.4072531) / mu.se > 10, `mutant: sq8 minus one corner spans at ${mu.m.toFixed(4)}, far from 0.4073 (caught)`);
  // mutant 2: the paper's mechanism. Without the 0.9 plateau the integrator should die; with it, survive.
  const alive = wmode => [0, 1, 2].filter(r => { const c = run('B', 1000 * r + 7, { wmode, lat: 'sq4' }); return c.ig + c.ib > 0; }).length;
  const ac = alive('clamp'), al = alive('linear');
  ok(ac === 3 && al === 0, `case B, 3 runs: integrator alive ${ac}/3 with the plateau, ${al}/3 without (control works)`);
  console.log(fail ? `${fail} FAILED` : 'all passed'); return fail ? 1 : 0;
}

shelf/rhizome-twin.mjs:
// Checks that www/rhizome/perc.js (what the page runs) gives the same digits as shelf/perc-calib.mjs.
// usage: node shelf/rhizome-twin.mjs <absolute path to www/rhizome/perc.js> [samples=2000] [seed=1]
import { execFileSync } from 'node:child_process';
import { pathToFileURL, fileURLToPath } from 'node:url';
import path from 'node:path';
const [file, N = '2000', SEED = '1'] = process.argv.slice(2);
const { rng, spanAt } = await import(pathToFileURL(file).href);
const here = path.dirname(fileURLToPath(import.meta.url));
const ref = execFileSync('node', [path.join(here, 'perc-calib.mjs'), N, SEED], { encoding: 'utf8' })
  .split('\n').filter(l => l.startsWith('L=')).map(l => l.match(/mean=(\S+) ± (\S+)/).slice(1).join(' '));
const rand = rng(+SEED), mine = [];
for (const L of [32, 64, 128, 256]) {
  let s = 0, s2 = 0;
  for (let i = 0; i < +N; i++) { const p = spanAt(L, rand); s += p; s2 += p * p; }
  const m = s / +N, se = Math.sqrt((s2 / +N - m * m) / (+N - 1));
  mine.push(`${m.toFixed(5)} ${se.toFixed(5)}`);
}
// the mutant must move far off p_c, or the check can't fail
const r2 = rng(3); let b = 0; for (let i = 0; i < 200; i++) b += spanAt(64, r2, true); b /= 200;
const same = ref.length === 4 && ref.every((x, i) => x === mine[i]);
console.log('perc-calib:', ref.join(' | ')); console.log('page code: ', mine.join(' | '));
console.log('mutant (no right link) L=64 mean', b.toFixed(4));
if (!same || b < 0.68) { console.log('FAIL'); process.exit(1); } console.log('ok: same digits, mutant caught');

shelf/rk-figure.mjs:
// rk-figure.mjs (Morphyx, 2026-10-07). CHOICE research piece 1, the figure half. Runs with the net off.
// usage: node shelf/rk-figure.mjs research/rotation-keys [out.svg]
// A key is "shared" if 2 or more distinct DIDs held it in any op we fetched (key-dids.json). A multi-user PDS signs
// every genesis it makes with its own key, so that key is shared. The log records keys, never who holds them.
//  operator-made: the genesis op includes a shared key (a PDS operator made the DID)
//  self-minted:   no shared key at genesis (made by whoever generated its keys: a self-hoster, or a minting run)
//  took a key:    an operator-made DID whose current rotation keys include an unshared key that wasn't in genesis
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
const [dir = 'research/rotation-keys', svgOut] = process.argv.slice(2);
const kd = JSON.parse(readFileSync(`${dir}/key-dids.json`, 'utf8'));
const shared = (k) => (kd[k] ?? 0) >= 2;
function wilson(x, n, z = 1.96) {
  if (!n) return [0, 1];
  const p = x / n, d = 1 + z * z / n, c = (p + z * z / (2 * n)) / d, h = (z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))) / d;
  return [Math.max(0, c - h), Math.min(1, c + h)];
}
const rows = [];
for (const f of readdirSync(dir).filter((f) => /^sample-\d{4}-\d\d\.json$/.test(f)).sort()) {
  const month = f.slice(7, 14), s = JSON.parse(readFileSync(`${dir}/${f}`, 'utf8')).filter((r) => r.status === 200 && !r.tombstone);
  const op = s.filter((r) => r.genesisKeys.some(shared));
  const took = op.filter((r) => r.keys.some((k) => !shared(k) && !r.genesisKeys.includes(k)));
  rows.push({ month, n: s.length, selfMinted: s.length - op.length, operatorMade: op.length, took: took.length, ci: wilson(took.length, op.length), selfCi: wilson(s.length - op.length, s.length) });
}
const pct = (x) => (100 * x).toFixed(2) + '%';
console.log('month    n  self-minted  operator-made  took-a-key  took 95% CI');
for (const r of rows) console.log(r.month, String(r.n).padStart(4), String(r.selfMinted).padStart(11), String(r.operatorMade).padStart(14), String(r.took).padStart(11), ` [${pct(r.ci[0])}, ${pct(r.ci[1])}]`);
const byYear = {};
for (const r of rows) { const y = r.month.slice(0, 4); byYear[y] ??= { op: 0, took: 0 }; byYear[y].op += r.operatorMade; byYear[y].took += r.took; }
for (const [y, v] of Object.entries(byYear)) console.log(`cohort ${y}: ${v.took}/${v.op} operator-made DIDs took a key, 95% CI [${pct(wilson(v.took, v.op)[0])}, ${pct(wilson(v.took, v.op)[1])}]`);

if (svgOut) {
  const W = 1000, H = 560, L = 70, R = 20, T = 70, B = 70, pw = W - L - R, ph = (H - T - B - 40) / 2, bw = pw / rows.length;
  const y1 = (v) => T + ph - v * ph, y2 = (v) => T + ph + 40 + ph - (v / 0.25) * ph;
  let g = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="Helvetica,Arial,sans-serif">`;
  g += `<rect width="${W}" height="${H}" fill="#fff"/><text x="${L}" y="28" font-size="20" font-weight="bold">Who made each DID, and did its owner ever take a key? (~200 per month)</text>`;
  g += `<text x="${L}" y="${T - 10}" font-size="14">Top: share self-minted (no PDS operator's key at genesis), 95% Wilson interval. 0 to 100%.</text>`;
  g += `<text x="${L}" y="${T + ph + 30}" font-size="14">Bottom: of DIDs a PDS operator made, share that later added a key of their own. 0 to 25%. Dot = 0.</text>`;
  rows.forEach((r, i) => {
    const x = L + i * bw, f = r.selfMinted / (r.n || 1);
    g += `<rect x="${x + 2}" y="${y1(f)}" width="${bw - 4}" height="${y1(0) - y1(f)}" fill="#b5523b"/>`;
    g += `<line x1="${x + bw / 2}" x2="${x + bw / 2}" y1="${y1(r.selfCi[1])}" y2="${y1(r.selfCi[0])}" stroke="#333"/>`;
    const p = r.took / (r.operatorMade || 1);
    if (r.took) g += `<rect x="${x + 2}" y="${y2(p)}" width="${bw - 4}" height="${y2(0) - y2(p)}" fill="#2f5d8a"/>`;
    else g += `<circle cx="${x + bw / 2}" cy="${y2(0) - 3}" r="2" fill="#2f5d8a"/>`;
    g += `<line x1="${x + bw / 2}" x2="${x + bw / 2}" y1="${y2(Math.min(r.ci[1], 0.25))}" y2="${y2(r.ci[0])}" stroke="#333"/>`;
    if (r.month.endsWith('-01')) g += `<text x="${x}" y="${H - B + 20}" font-size="13">${r.month}</text>`;
  });
  for (const [v, f] of [[0, y1], [0.5, y1], [1, y1], [0, y2], [0.1, y2], [0.2, y2]]) g += `<text x="${L - 8}" y="${f(v) + 4}" font-size="12" text-anchor="end">${Math.round(v * 100)}%</text><line x1="${L}" x2="${W - R}" y1="${f(v)}" y2="${f(v)}" stroke="#ccc" stroke-width="0.5"/>`;
  g += `<text x="${L}" y="${H - 28}" font-size="12">Shared key = held by 2+ DIDs we saw. Since 2025-04 most self-minted DIDs are bulk runs (P-256 keys, filler handles,</text><text x="${L}" y="${H - 12}" font-size="12">PDS hosts that don't serve them). Clustered sample: intervals are too narrow. research/rotation-keys, Morphyx 2026-10-07</text></svg>`;
  writeFileSync(svgOut, g);
}

shelf/rk-sample.mjs:
// rk-sample.mjs (Morphyx, 2026-10-07). CHOICE research piece 1: the fetch half.
// Seeded, stratified sample of DIDs by creation month from plc.directory, archived as compact
// extracts plus sha256 of every raw byte fetched. The figure is computed by rk-figure.mjs, net off.
// usage: node shelf/rk-sample.mjs <outdir> [perStart=50] [starts=4] [seed=20261007]
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync, existsSync } from 'node:fs';

const [out = 'research/rotation-keys', PER = '50', STARTS = '4', SEED = '20261007'] = process.argv.slice(2);
const per = +PER, starts = +STARTS;
mkdirSync(out, { recursive: true });
const sha = (s) => createHash('sha256').update(s).digest('hex');

// mulberry32, so the start times can be re-drawn exactly
function rng(a) { return () => { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const rand = rng(+SEED);

async function get(url, tries = 6) {
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(url);
      const body = await r.text();
      if (r.status === 429 || r.status >= 500) { await new Promise((z) => setTimeout(z, 2000 * (i + 1))); continue; }
      return { status: r.status, body, at: new Date().toISOString() };
    } catch { await new Promise((z) => setTimeout(z, 2000 * (i + 1))); }
  }
  return { status: 0, body: '', at: new Date().toISOString() };
}

const months = [];
for (let y = 2022, m = 11; y < 2026 || (y === 2026 && m <= 9); m === 12 ? (y++, m = 1) : m++) months.push([y, m]);

const manifest = [];
const sampledKeys = new Set(); // every fetch: url, time, status, sha256, bytes
const keyDids = new Map(); // rotation key -> Set of DIDs seen holding it in any op of any export page
const note = (k, did) => { if (!keyDids.has(k)) keyDids.set(k, new Set()); keyDids.get(k).add(did); };
const keysOf = (op) => op.type === 'create' ? [op.recoveryKey, op.signingKey].filter(Boolean) : (op.rotationKeys || []);

for (const [y, m] of months) {
  const t0 = Date.UTC(y, m - 1, 1), t1 = Date.UTC(m === 12 ? y + 1 : y, m === 12 ? 0 : m, 1);
  const label = `${y}-${String(m).padStart(2, '0')}`;
  const picks = [];
  const seen = new Set();
  const draws = Array.from({ length: starts }, () => new Date(t0 + Math.floor(rand() * (t1 - t0))).toISOString()).sort();
  for (const after of draws) {
    const url = `https://plc.directory/export?count=1000&after=${after}`;
    const r = await get(url);
    manifest.push({ url, at: r.at, status: r.status, sha256: sha(r.body), bytes: Buffer.byteLength(r.body) });
    let got = 0;
    for (const line of r.body.split('\n')) {
      if (!line.trim()) continue;
      const e = JSON.parse(line);
      for (const k of keysOf(e.operation)) note(k, e.did);
      if (got < per && e.operation.prev === null && !seen.has(e.did) && e.createdAt < new Date(t1).toISOString()) {
        seen.add(e.did); picks.push({ did: e.did, created: e.createdAt, start: after }); got++;
      }
    }
  }
  // the audit log of each pick: its whole history, so current state and any later key changes
  const rows = [];
  for (let i = 0; i < picks.length; i += 10) {
    const batch = picks.slice(i, i + 10);
    const res = await Promise.all(batch.map((p) => get(`https://plc.directory/${p.did}/log/audit`)));
    res.forEach((r, j) => {
      const p = batch[j];
      const prov = { fetched: r.at, sha256: sha(r.body), bytes: Buffer.byteLength(r.body) }; // audit-log provenance lives in the row
      if (r.status !== 200) { rows.push({ ...p, status: r.status, ...prov }); return; }
      const log = JSON.parse(r.body);
      const live = log.filter((e) => !e.nullified);
      for (const e of log) for (const k of keysOf(e.operation)) note(k, e.did);
      const last = live[live.length - 1].operation;
      rows.push({
        ...p, status: 200, ops: log.length, nullified: log.length - live.length,
        tombstone: last.type === 'plc_tombstone',
        genesisKeys: keysOf(log[0].operation),
        keys: last.type === 'plc_tombstone' ? [] : keysOf(last),
        endpoint: last.type === 'create' ? last.service : last.services?.atproto_pds?.endpoint ?? null,
        keyChanges: live.slice(1).filter((e, i) => JSON.stringify(keysOf(e.operation)) !== JSON.stringify(keysOf(live[i].operation))).map((e) => e.createdAt),
        ...prov,
      });
    });
  }
  for (const r of rows) for (const k of [...(r.keys || []), ...(r.genesisKeys || [])]) sampledKeys.add(k);
  writeFileSync(`${out}/sample-${label}.json`, JSON.stringify(rows));
  console.error(label, picks.length, 'picks');
}
writeFileSync(`${out}/manifest.jsonl`, manifest.map((x) => JSON.stringify(x)).join('\n') + '\n');
// only the keys our sampled DIDs hold (a full map is megabytes); each with how many distinct DIDs held it
const counts = {}; for (const k of sampledKeys) counts[k] = keyDids.get(k)?.size ?? 0;
writeFileSync(`${out}/key-dids.json`, JSON.stringify(counts));
console.error('fetches', manifest.length, 'keys', keyDids.size);

shelf/rota-grid.mjs:
// node shelf/rota-grid.mjs <dir> SEED:COUNT [SEED:COUNT ...]
// Runs rota-stress for each seed and prints one line per seed: made / unlawful / gave up /
// refused (and how many of those were unnamed, i.e. "exhaustive search"), worst time.
// Lists every GAVE UP / UNLAWFUL line. Exit 1 if any unlawful, gave-up or unnamed refusal.
// Morphyx (from scratch-mx-grid, rota 4th).
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const [dir = '.', ...specs] = process.argv.slice(2);
if (!specs.length) { console.error('usage: node shelf/rota-grid.mjs <dir> SEED:COUNT [...]'); process.exit(2); }
const stress = join(dirname(fileURLToPath(import.meta.url)), 'rota-stress.mjs');
let bad = 0;
for (const spec of specs) {
  const [s, c] = spec.split(':');
  const r = spawnSync(process.execPath, [stress, dir, 'stress', s, c || '1000'], { encoding: 'utf8', maxBuffer: 64 << 20 });
  const lines = r.stdout.split('\n');
  const a = lines.findIndex((x) => x === '{'), b = lines.findIndex((x) => x === '}');
  if (a < 0 || b < 0) { console.log(`seed ${s}: no summary\n${r.stderr.slice(0, 400)}`); bad++; continue; }
  const j = JSON.parse(lines.slice(a, b + 1).join('\n'));
  // Only the per-team message lines; the summary's tally line also contains "exhaustive".
  const unnamed = lines.filter((x) => /^\s+no rota.*exhaustive/.test(x)).length;
  const refused = Object.values(j.refused).reduce((p, q) => p + q, 0);
  console.log(`seed ${s}/${c}: made ${j.made} unlawful ${j.unlawful} gaveUp ${j.gaveUp} refused ${refused} (unnamed ${unnamed}) ${lines.find((x) => x.startsWith('worst')) || ''}`);
  for (const x of lines.filter((x) => /^(GAVE|UNLAW)/.test(x))) console.log('  ', x.slice(0, 160));
  bad += j.unlawful + j.gaveUp + unnamed;
}
process.exit(bad ? 1 : 0);

