      s.jobs[name] = await job({ agent, now, state: s.jobs[name] });
    } catch (e) {
      // a job that throws keeps its old state, so it can't lose a seed or post twice
      s.jobs[name] = { ...(s.jobs[name] || {}), lastError: String((e && e.message) || e).slice(0, 300) };
