# Modulo 2026-10-17. python3 -I fold.py <coarse rows dir> <this dir>. Folds orig (coarse vortorus), perm, seed at t=8000.
import json,sys,glob,collections
d,me=sys.argv[1],sys.argv[2]
def st(rs):
