  for S,I in rs: c['D' if S+I==0 else 'I' if S==0 else 'S' if I==0 else 'B']+=1
  m=max(c.values()); w=[k for k in c if c[k]==m]
  return (w[0] if len(w)==1 else 'T'), c['B']
def grp(rows):
