    m=max(c.values()); w=[x for x in c if c[x]==m]; st[k]=w[0] if len(w)==1 else 'T'
  ps=sorted({k[1] for k in st}); hs=sorted({k[2] for k in st})
  for (s,p,h),v in st.items():
