for (const h of H) for (const p of P) for (let r = 0; r < 10; r++) {
  const seed = seedOf(r), o = run([p, s, h], seed, { L }, T);
  console.log(JSON.stringify({ L, s, p, h, T, seed, S: +(o.sg + o.sb).toFixed(2), I: +(o.ig + o.ib).toFixed(2), sg: o.sg, ig: o.ig }));
