// The paper's seven habitats: [p good fraction, s block side, h]
export const CASES = { B:[0.5,2,0.9], A1:[0.25,2,0.9], A2:[0.5,1,0.9], A3:[0.5,2,0.8], C1:[0.75,2,0.9], C2:[0.5,5,0.9], C3:[0.5,2,1.0] };
