for (const [vn, o] of variants) for (const cs of Object.keys(CASES)) {
  const rs=[]; for (let r=0;r<runs;r++) rs.push(run(cs, seedOf(r), o, T));
  const s=rs.map(x=>x.sg+x.sb), i=rs.map(x=>x.ig+x.ib);
