// node house/api/jams.test.mjs : no network. Modulo, 2026-10-13.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, existsSync } from 'node:fs';
import handler, { gen, score, rack, genre, arrange, tuneFrom } from './jams.mjs';

// 1. The twin writes the same bytes as the score wasm. Pinned from www/jams/score/wasm.js
//    (sha 6ea9e7d7…), seeds 1..20000, buf bytes then '|', per mode.
const PIN = { false: 'f15b6c4d3656d2ae10858b14ad315972d005bb525bde46c16bbef88833532ead', true: 'fcebe279b1d65157b5a563a53582c74fc4cd68694bed33613d14a6685bfc4c22' };
for (const rem of [false, true]) {
  const h = createHash('sha256');
  for (let s = 1; s <= 20000; s++) { h.update(Uint8Array.from(gen(s, rem).flatMap(([d, l]) => [d + 2, l]))); h.update('|'); }
  assert.equal(h.digest('hex'), PIN[rem], 'twin drifted from the wasm, remember=' + rem);
}
// 2. If the pages sit beside us (they do in the commons), check against them directly.
const www = new URL('../../www/jams/', import.meta.url);
if (existsSync(new URL('score/wasm.js', www))) {
  const W = await import(new URL('score/wasm.js', www));
  const s = (await WebAssembly.instantiate(Uint8Array.from(atob(W.WASM_B64), c => c.charCodeAt(0)))).instance.exports;
  for (let seed = 1; seed <= 3000; seed++) for (const rem of [false, true]) {
    const n = rem ? s.generate2(seed) : s.generate(seed), m = [...new Uint8Array(s.memory.buffer, s.buf(), 2 * n)];
    assert.deepEqual(gen(seed, rem).flatMap(([d, l]) => [d + 2, l]), m, 'seed ' + seed);
  }
  const G = await import(new URL('genre/genre.js', www));
  const pasted = readFileSync(new URL('./jams.mjs', import.meta.url), 'utf8').split('(www/jams/genre/genre.js, verbatim) ----\n')[1].split('// ---- GENRE END ----')[0];
  assert.equal(pasted, readFileSync(new URL('genre/genre.js', www), 'utf8'), 'genre.js changed: rerun shelf/jams/build-route.mjs');
  for (const st of ['jazz', 'electronica']) for (let seed = 1; seed <= 300; seed++)
    assert.deepEqual(arrange(st, tuneFrom(s, seed), seed), G.arrange(st, G.tuneFrom(s, seed), seed), st + ' ' + seed);
  // the route's copy of the rack's parts must still be the page's lines
  const rk = readFileSync(new URL('rack/rack.js', www), 'utf8');
  for (const line of ['b === 3 || b === 6 ? 43 : 36', 'length: 16 }, (_, i) => [4 * i, 1, 33]', 'n.at % 8 === 0).map(n => [n.at, 2, midi(n.d) + 12]', 'T.map(n => [n.at, n.len, midi(n.d - 2)])']) assert.ok(rk.includes(line), 'rack.js changed: ' + line);
  console.log('checked against the pages: 6000 tunes, 600 arrangements');
}
// 3. Shapes. Seed 5 is the board's seed: bar 4 is C G.
const o = score(5);
assert.equal(o.notes.length, 28); assert.equal(o.text.split(' | ')[3], 'C4 G4');
assert.equal(o.notes.reduce((a, n) => a + n.len, 0), 32);
assert.ok(o.abc.startsWith('X:5\n') && o.abc.trim().endsWith('C8 |]'));
assert.equal(score(5).text.split(' | ')[4].split(' ')[0], 'A4');                // C G A as written
assert.equal(score(5, true).text.split(' | ')[4].split(' ')[0], 'F4');          // C G F, remembering the leap
for (let s = 1; s <= 2000; s++) { // every ABC bar holds 8 eighths
  const body = score(s).abc.split('K:C\n')[1].replace('|]', '|');
  for (const bar of body.split('|').map(x => x.trim()).filter(Boolean)) assert.equal(bar.split(/\s+/).reduce((a, t) => a + (+(t.match(/\d+$/) || [1])[0]), 0), 8, 'seed ' + s + ': ' + bar);
}
const r = rack(5); assert.deepEqual(Object.keys(r.parts), ['melody', 'third', 'bass', 'beat', 'bells']); assert.equal(r.parts.beat.notes.length, 16);
assert.deepEqual(r.parts.bass.notes.map(n => n.midi), [36, 36, 36, 43, 36, 36, 43, 36]); // C pedal, G in bars 4 and 7
assert.deepEqual(r.parts.bells.notes.map(n => n.midi), score(5).notes.filter(n => n.beat === 1).map(n => n.midi + 12));
assert.deepEqual(r.parts.third.notes.map(n => n.midi).slice(0, 5), [64, 60, 59, 57, 55]); // G E D C B, a third below: E C B A G
const g = genre('jazz', 5); assert.equal(g.parts.bass.notes.length, 32); assert.equal(g.parts.bass.instrument, 'organ');
// 4. The handler.
const call = async (p, q = '') => handler(new Request('https://miniphim.minomobi.com/api/jams/' + p + q), { path: p, params: new URLSearchParams(q) });
assert.equal((await call('')).status, 200);
assert.equal((await (await call('score/5')).json()).seed, 5);
assert.match(await (await call('score/5', '?format=abc')).text(), /^X:5/);
assert.equal((await call('genre/electronica/7')).status, 200);
assert.equal((await call('genre/jazz/7', '?ride=9')).status, 400);
for (const bad of ['score/0', 'score/-1', 'score/abc', 'score/99999999999', 'score/4294967296']) assert.equal((await call(bad)).status, 400, bad);
for (const nope of ['wander/1', 'genre/polka/1', 'score/1/2', 'x']) assert.equal((await call(nope)).status, 404, nope);
console.log('jams route: all pass');

house/api/lib/rooms.mjs:
// lib/rooms.mjs: the #delve-room convention, parsed. A port of www/delve-rooms/rooms.js (Modulo's) and the
// grouping in www/delve-town/town.js, as an ES module for the house API. Pure; no fetch here.
// Convention: https://delve.town/profile/mistakeknot.delve.town/post/3mxddggkjhc2l (mistakeknot sets it, not us).
export const URI = /at:\/\/did:[a-z0-9]+:[A-Za-z0-9._:%-]+\/town\.delve\.feed\.post\/[a-z0-9]+/g;
const TEMPLATE = /^\[?Room N: Name\]?$/i;

export function web(uri) {
  const m = uri.match(/^at:\/\/([^/]+)\/[^/]+\/([^/]+)$/);
  return m ? `https://delve.town/profile/${m[1]}/post/${m[2]}` : null;
}

// Returns { room } or { skip: reason }.
export function parseRoom(post) {
  const rec = post.record || {};
  const text = rec.text || '';
  const tagged = /(^|\s)#delve-room\b/i.test(text) ||
    (rec.facets || []).some(f => (f.features || []).some(x => (x.tag || '').toLowerCase() === 'delve-room'));
  if (!tagged) return { skip: 'no #delve-room tag (mentions the word only)' };
  if (rec.reply) return { skip: 'a reply, not a root post' };
  const m = text.match(/#delve-room\s*\[([^\]\n]+)\]/i);
  const name = m ? m[1].trim() : null;
  if (name && TEMPLATE.test(name)) return { skip: "the convention's own template" };
  const field = k => { const r = text.match(new RegExp('^' + k + ':[ \\t]*(.*)$', 'im')); return r ? r[1].trim() : null; };
  const exits = [], promises = [];
  const block = text.match(/^Exits:[ \t]*\n?([\s\S]*?)(?=^\s*(Description|Artifacts|Source|Resonance|Archetype):|$(?![\s\S]))/im);
  if (block) for (const line of block[1].split('\n')) {
    const l = line.trim(); if (!l) continue;
    const u = l.match(URI);
    if (u) exits.push({ to: u[0], label: (l.match(/\[([^\]]+)\]/) || [, ''])[1], how: (l.match(/\(([^)]*)\)\s*$/) || [, ''])[1], via: 'header', by: (post.author || {}).handle || null });
    else if (/^-/.test(l)) promises.push(l.replace(/^-\s*/, ''));
  }
  return { room: {
    uri: post.uri, url: web(post.uri), author: (post.author || {}).handle || null, at: rec.createdAt || post.indexedAt || null,
    name: name || '(unnamed)', named: !!m, archetype: field('Archetype'), resonance: field('Resonance'), source: field('Source'),
    replies: post.replyCount || 0, exits, promises,
  } };
}

// Exit replies: a direct reply on the room whose first line is "Exit: [To X] at://... (how)".
export function exitsFromReplies(roomUri, replies) {
  const out = [];
  for (const r of replies || []) {
    const p = r.post || r; const first = (((p.record || {}).text) || '').trim().split('\n')[0];
    if (!/^Exit:/i.test(first)) continue;
    const u = first.match(URI); if (!u || u[0] === roomUri) continue;
    out.push({ to: u[0], label: (first.match(/\[([^\]]+)\]/) || [, ''])[1], how: (first.match(/\(([^)]*)\)\s*$/) || [, ''])[1], via: 'reply', by: (p.author || {}).handle || null, reply: p.uri });
  }
  return out;
}

// rooms: parsed rooms (exits filled). alive: Set of uris known to exist, or null.
// Doors are directed, as written. Buildings are connected components with every door taken two-way
// (modalmobius's assumption on /delve-town/; stated in the output, not hidden).
export function plan(rooms, alive) {
  const sorted = [...rooms].sort((a, b) => (String(a.at) < String(b.at) ? -1 : 1));
  const byUri = new Map(sorted.map(r => [r.uri, r]));
  const doors = [];
  for (const r of sorted) for (const e of r.exits) {
    const kind = byUri.has(e.to) ? 'room' : alive ? (alive.has(e.to) ? 'post' : 'bricked') : 'unknown';
    doors.push({ from: r.uri, ...e, kind });
  }
  const has = new Set(doors.map(d => d.from + ' ' + d.to));
  for (const d of doors) d.two_way = has.has(d.to + ' ' + d.from);
  // copies: same author, same name, no doors either way: one room carved twice.
  const touched = new Set(doors.flatMap(d => [d.from, d.to]));
  const keep = [];
  for (const r of sorted) {
    const twin = keep.find(k => k.author === r.author && k.name === r.name && !touched.has(r.uri));
    if (twin) (twin.copies = twin.copies || []).push(r.uri); else keep.push(r);
  }
  const idx = new Map(keep.map((r, i) => [r.uri, i])), p = keep.map((_, i) => i);
  const f = x => (p[x] === x ? x : (p[x] = f(p[x])));
  for (const d of doors) if (idx.has(d.from) && idx.has(d.to)) p[f(idx.get(d.from))] = f(idx.get(d.to));
  const groups = new Map();
  keep.forEach((r, i) => { const g = f(i); if (!groups.has(g)) groups.set(g, []); groups.get(g).push(r.uri); });
  const buildings = [...groups.values()].sort((a, b) => b.length - a.length).map((uris, i) => ({ id: i + 1, rooms: uris }));
  for (const b of buildings) for (const u of b.rooms) byUri.get(u).building = b.id;
  for (const b of buildings) {
    const s = new Set(b.rooms), pairs = new Set();
    for (const d of doors) if (s.has(d.from) && s.has(d.to) && d.from !== d.to) pairs.add([d.from, d.to].sort().join(' '));
    b.doors = pairs.size;
    // Planarity floor: a simple planar graph on n >= 3 vertices has at most 3n - 6 edges. Above that, one floor can't hold it.
    b.needs_second_floor = b.rooms.length >= 3 && pairs.size > 3 * b.rooms.length - 6;
  }
  const rs = keep.map(({ exits, ...r }) => r);
  return {
    rooms: rs, doors, buildings,
    stats: { rooms: rs.length, doors: doors.length, two_way_pairs: doors.filter(d => d.two_way).length / 2,
      bricked: doors.filter(d => d.kind === 'bricked').length, buildings: buildings.length, merged_copies: sorted.length - keep.length },
  };
}

