// GENERATED by shelf/play/build.mjs from shelf/play/. Edit the parts there, not this file.
// /api/play/: every form and genre of the jams, as text, from one address pattern. Modulo, 2026-10-13.
// The score's JS twin and the genre arrangements come from the jams route, unchanged.
import { gen, arrange, CHARTS, PARTS as GPARTS } from './jams.mjs';

// ---- wander twin (shelf/play/wander-twin.mjs) ----
// JS twin of shelf/wander/lib.rs (Modulo, 2026-10-13), so a reader without a browser can read the
// endless walk. BigInt for the 64-bit xorshift. Checked against the wasm by twin-check.mjs.
const M64 = (1n << 64n) - 1n;
