  third:  { kind: 0, gain: 0.12, notes: T => T.map(n => [n.at, n.len, midi(n.d - 2)]) },
  bass:   { kind: 5, gain: 0.22, notes: () => [0, 1, 2, 3, 4, 5, 6, 7].map(b => [8 * b, 8, b === 3 || b === 6 ? 43 : 36]) },
  beat:   { kind: 4, gain: 0.50, notes: () => Array.from({ length: 16 }, (_, i) => [4 * i, 1, 33]) },
