    notes.sort((a, b) => a.t - b.t || (a.part < b.part ? -1 : 1));
    const sp = T.map(n => spell(key, n.d));
    let abc = '', t = 0;
    for (let j = 0; j < T.length; j++) { abc += sp[j].abc + (T[j].len === 1 ? '' : T[j].len); t += T[j].len; abc += t % 8 === 0 ? (t === 64 ? ' |' : ' | ') : ' '; }
