    commit: sha(seed).toString('hex'),
    calls: shuffle(r(1, 75), stream('calls')),
    card: (did) => {
      const cols = r(0, 5).map((c) => shuffle(r(15 * c + 1, 15), stream(`${did}:${c}`)).slice(0, 5));
      const g = r(0, 5).map((row) => r(0, 5).map((c) => cols[c][row])); g[2][2] = 0; return g;
