  if ((profile?.labels?.values || []).some((l) => l?.val === 'bot')) return 'label';
  if (/\(bot\)/i.test(profile?.displayName || '')) return 'name';
  return null;
}
export const sortAt = (createdAt, seen) => {
  const c = Date.parse(createdAt), s = Date.parse(seen);
