    }
    return out;
  }

  // Edges keyed on URIs only. kind: 'room' (target is a mapped room), 'post' (exists, not a room), 'bricked' (gone), 'unknown'.
  function buildGraph(rooms, alive) {
    const byUri = new Map(rooms.map(r => [r.uri, r]));
