// Modulo, 2026-10-13. The page: the score's wasm writes the tune, genre.js arranges it,
// and the rack's own worklet and wasm (unchanged, from ../rack/) make the sound.
import * as S from '../score/wasm.js';
import * as R from '../rack/wasm.js';
import * as G from './genre.js';
import * as H from '../handed.js';
const $ = id => document.getElementById(id);
const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const hex = async b => [...new Uint8Array(await crypto.subtle.digest('SHA-256', b))].map(x => x.toString(16).padStart(2, '0')).join('');
const rackBytes = b64(R.WASM_B64), scoreBytes = b64(S.WASM_B64);
$('sha').textContent = `rack ${(await hex(rackBytes)) === R.WASM_SHA ? R.WASM_SHA.slice(0, 12) + '… matches' : 'DOES NOT MATCH'}, score ${(await hex(scoreBytes)) === S.WASM_SHA ? S.WASM_SHA.slice(0, 12) + '… matches' : 'DOES NOT MATCH'}`;
const score = (await WebAssembly.instantiate(scoreBytes)).instance.exports;
const KINDS = ['organ', 'pluck', 'bell', 'reed', 'kick', 'strings'];
const hz = m => 440 * 2 ** ((m - 69) / 12);
let style = 'jazz', ac, node;
const Q = new URLSearchParams(location.search);
if (Q.get('style') in G.PARTS) style = Q.get('style');
if (+Q.get('seed') > 0) $('seed').value = +Q.get('seed');
function drawParts() {
  $('parts').innerHTML = '';
  for (const [name, p] of Object.entries(G.PARTS[style])) {
    const row = document.createElement('label'); row.className = 'part';
    row.innerHTML = `<span>${name}</span><select id="p-${name}"><option value="-1">off</option>${KINDS.map((k, i) => `<option value="${i}"${i === p.kind ? ' selected' : ''}>${k}</option>`).join('')}</select>`;
    $('parts').appendChild(row);
  }
  for (const b of document.querySelectorAll('[data-style]')) b.setAttribute('aria-pressed', b.dataset.style === style);
  $('swingrow').style.display = style === 'jazz' ? '' : 'none';
  $('tempo').value = G.DEFAULT_BPM[style]; $('bpm').textContent = $('tempo').value;
}
for (const b of document.querySelectorAll('[data-style]')) b.onclick = () => { style = b.dataset.style; drawParts(); play(); };
$('tempo').oninput = () => $('bpm').textContent = $('tempo').value;
$('ride').oninput = () => { const r = +$('ride').value; $('rv').textContent = r.toFixed(2); $('sv').textContent = (1 + 0.5 * (r - 1)).toFixed(2); };
async function play() {
  if (!ac) {
    ac = new AudioContext(); ac.resume(); // inside the tap, before any await, or phones stay muted
    await ac.audioWorklet.addModule('../rack/worklet.js');
    node = new AudioWorkletNode(ac, 'rack', { outputChannelCount: [2] }); node.connect(ac.destination);
    await new Promise(ok => { node.port.onmessage = ({ data }) => data.ready && ok(); node.port.postMessage({ wasm: rackBytes.buffer.slice(0) }); });
    node.port.onmessage = ({ data }) => { $('meter').textContent = `${data.at.toFixed(1)} s · voices ${data.sounding}, most at once ${data.peak} of 192` + (data.drop ? ` · ${data.drop} dropped` : '') + (data.done ? ' · done' : ''); };
  }
  await ac.resume();
  const seed = +$('seed').value || 1, bpm = +$('tempo').value, spb = 60 / bpm * ac.sampleRate, parts = G.PARTS[style];
  const T = G.tuneFrom(score, seed), ev = [];
  for (const e of G.arrange(style, T, seed, { ride: +$('ride').value })) {
    const kind = +$('p-' + e.part).value; if (kind < 0) continue;
    ev.push([Math.round(e.t * spb + 0.05 * ac.sampleRate), kind, hz(e.m), parts[e.part].gain * e.g, Math.round(e.d * spb), e.part]);
  }
  ev.sort((a, b) => a[0] - b[0]);
  history.replaceState(null, '', `?style=${style}&seed=${seed}`);
  $('api').textContent = $('api').href = `/api/jams/genre/${style}/${seed}` + (style === 'jazz' ? `?ride=${$('ride').value}` : '');
  $('tune').innerHTML = `${style}, seed ${seed}: ${ev.length} notes. The melody is <a href="../score/?seed=${seed}">/score/?seed=${seed}</a>; <a href="../rack/?seed=${seed}">the rack</a> plays it as written.`;
  node.port.postMessage({ events: H.start({ name: `${style}-seed${seed}`, style, seed, bpm, ride: style === 'jazz' ? +$('ride').value : null, sampleRate: ac.sampleRate, rack_sha: R.WASM_SHA, score_sha: S.WASM_SHA }, ev) });
}
$('play').onclick = play;
$('stop').onclick = () => node && node.port.postMessage({ stop: true });
drawParts();

www/jams/handed.js:
// Modulo, 2026-10-13, for trinity.automata.garden: "the events handed to the synth, not a second
// implementation trying to predict them", at the same address where somebody presses play.
// Every array a page posts to the rack's worklet passes through here first, unchanged, and is kept.
// The Events link hands it back as JSON: these are the very objects the audio thread was given.
// Event: [startSample, kind, hz, gain, lengthSamples, part]. The worklet reads the first five.
const KINDS = ['organ', 'pluck', 'bell', 'reed', 'kick', 'strings'];
let log = null;
export function start(meta, ev) {
  log = { ...meta, page: location.href, at: new Date().toISOString(), events: ev.slice() };
  show();
  return ev;
}
export function more(ev) { if (log) { log.events.push(...ev); show(); } return ev; }
function show() {
  const a = document.getElementById('events'); if (!a) return;
  a.hidden = false;
  a.textContent = `Events: the ${log.events.length} notes handed to the synth (JSON)`;
}
export function json() {
  if (!log) return null;
  const midi = hz => Math.round(1200 * Math.log2(hz / 440)) / 100 + 69; // fractional when a copy is detuned
  return JSON.stringify({
    what: 'Every note this page handed to the rack worklet, in the order handed, copied before it was posted.',
    fields: 'start and length are in samples of the page\'s AudioContext; midi is computed from hz; part names the line it came from.',
    ...log, events: undefined, kinds: KINDS,
    notes: log.events.map(e => ({ start: e[0], part: e[5] ?? null, kind: KINDS[e[1]], hz: +e[2].toFixed(4), midi: midi(e[2]), gain: +e[3].toFixed(5), length: e[4] })),
  }, null, 1);
}
const a = typeof document !== 'undefined' && document.getElementById('events');
if (a) a.onclick = ev => {
  ev.preventDefault(); const s = json(); if (!s) return;
  const url = URL.createObjectURL(new Blob([s], { type: 'application/json' }));
  const d = document.createElement('a'); d.href = url; d.download = `${log.name}-events.json`;
  document.body.appendChild(d); d.click(); d.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
};

www/jams/jams.css:
/* The jams' house style, one file for every page under /jams/. Modulo, 2026-10-13.
   The choice: a desk with a sheet of paper on it. The score is engraving, black on white, so the
   staff stays a white sheet; the desk around it is warm paper. One accent colour, the blue that
   already marks a changed note on /score/. Numbers and code in monospace, because they are
   the parts you're meant to check. Change the look here, and every jams page changes with it. */
:root{--desk:#f4efe4;--sheet:#fff;--ink:#1f1c17;--quiet:#6b6458;--rule:#d8cfbd;--accent:#2457c5;--code:#ebe4d4}
html{background:var(--desk)}
body{font:16px/1.55 system-ui,sans-serif;max-width:860px;margin:0 auto 3em;padding:0 1em;color:var(--ink);background:var(--desk)}
h1{font:600 2em/1.2 Georgia,"Iowan Old Style",serif;margin:.6em 0 .3em}
h2,h3{font-family:Georgia,"Iowan Old Style",serif;font-weight:600;border-top:1px solid var(--rule);padding-top:.6em;margin-top:1.6em}
a{color:var(--accent)}
nav.jams{display:flex;flex-wrap:wrap;gap:.2em 1.1em;align-items:baseline;padding:.8em 0 .6em;border-bottom:1px solid var(--rule);font-size:15px}
nav.jams b{font-family:Georgia,serif;font-size:17px;margin-right:.4em}
nav.jams a{text-decoration:none}nav.jams a[aria-current]{color:var(--ink);font-weight:600;border-bottom:2px solid var(--accent)}
button,input,select{font:inherit;padding:.3em .7em;border:1px solid var(--quiet);border-radius:3px;background:var(--sheet);color:var(--ink)}
button{cursor:pointer}button:hover{border-color:var(--accent)}
button[aria-pressed=true]{font-weight:bold;outline:2px solid var(--accent)}
svg{max-width:100%}
#staff svg,.sheet{width:100%;height:auto;background:var(--sheet);border:1px solid var(--rule);box-shadow:0 1px 3px #0001}
pre{background:var(--code);padding:1em;overflow-x:auto;font-size:13px;border-radius:3px}
code,pre,#meter,.num{font-family:ui-monospace,"SF Mono",Menlo,Consolas,monospace}
code{font-size:.9em}
small,#meter{color:var(--quiet)}
.on{color:#b3261e}
.part{display:inline-flex;gap:.4em;align-items:center;margin:.2em 1em .2em 0}
.part span{min-width:4.5em}
table{border-collapse:collapse;font-size:14px}td,th{padding:.15em .8em;text-align:right;border-bottom:1px solid var(--rule)}td:first-child,th:first-child{text-align:left}

www/jams/play.js:
// The jams player (Modulo, 2026-10-13): one page for every form (track, wander) and genre
// (garden, jazz, electronica), heard as sound and readable as text while it plays.
// Tunes come from the Rust (score and wander wasm); core.js arranges them, the same file the
// /api/play/ route runs; the rack (Rust, in the audio thread) makes the sound.
import * as S from './score/wasm.js';
import * as WD from './rack/wander-wasm.js';
import * as R from './rack/wasm.js';
import * as G from './genre/genre.js';
import * as H from './handed.js';
import { jam, partsOf, KINDS, GENRES, FORMS, BPM, noteName } from './core.js';
const $ = id => document.getElementById(id);
const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const hex = async b => [...new Uint8Array(await crypto.subtle.digest('SHA-256', b))].map(x => x.toString(16).padStart(2, '0')).join('');
const rackB = b64(R.WASM_B64), scoreB = b64(S.WASM_B64), wB = b64(WD.WASM_B64);
const ok = async (b, sha) => (await hex(b)) === sha ? sha.slice(0, 12) + '… matches' : 'DOES NOT MATCH';
$('sha').textContent = `rack ${await ok(rackB, R.WASM_SHA)} · score ${await ok(scoreB, S.WASM_SHA)} · wander ${await ok(wB, WD.WASM_SHA)}`;
const score = (await WebAssembly.instantiate(scoreB)).instance.exports, wnd = (await WebAssembly.instantiate(wB)).instance.exports;
const DEPS = {
  tune(seed) { const n = score.generate(seed >>> 0), m = new Uint8Array(score.memory.buffer, score.buf(), 2 * n); return Array.from({ length: n }, (_, i) => [m[2 * i] - 2, m[2 * i + 1]]); },
  walker(seed) { wnd.start(seed >>> 0); return { draw: n => wnd.draw(n), phrase() { const n = wnd.phrase(), m = new Uint8Array(wnd.memory.buffer, wnd.buf(), 9 + 2 * n);
    return { key: m[0] - 64, bass: [...m.slice(1, 9)].map(b => b - 16), notes: Array.from({ length: n }, (_, i) => [m[9 + 2 * i] - 16, m[10 + 2 * i]]) }; } }; },
  arrange: G.arrange, CHARTS: G.CHARTS, GPARTS: G.PARTS,
};

const Q = new URLSearchParams(location.search);
let form = FORMS.includes(Q.get('form')) ? Q.get('form') : 'track', genre = GENRES.includes(Q.get('genre')) ? Q.get('genre') : 'garden';
if (+Q.get('seed') > 0) $('seed').value = +Q.get('seed');
// The page's own address carries the whole performance: anything not at its default (tempo, swing,
// drift, a part's instrument) goes in it, so two listeners with one link hear one performance.
let first = true;
if (Q.has('ride')) { const r = +Q.get('ride'); if (r >= 1 && r <= 3.5) { $('ride').value = r; $('rv').textContent = r.toFixed(2); } }
if (Q.get('drift') === '0') $('drift').checked = false;
const hz = m => 440 * 2 ** ((m - 69) / 12);
function drawParts(keep) {
  const old = {}; if (keep) for (const s of document.querySelectorAll('#parts select')) old[s.dataset.part] = s.value;
  $('parts').innerHTML = '';
  for (const [name, p] of Object.entries(partsOf(genre, DEPS))) {
    const row = document.createElement('label'); row.className = 'part';
    row.innerHTML = `<span>${name}</span><select data-part="${name}" id="p-${name}"><option value="-1">off</option>${KINDS.map((k, i) => `<option value="${i}"${i === p.kind ? ' selected' : ''}>${k}</option>`).join('')}</select>`;
    $('parts').appendChild(row);
    const q = first && Q.get(name); if (!keep && q) { const i = KINDS.indexOf(q); if (q === 'off') row.lastChild.value = -1; else if (i >= 0) row.lastChild.value = i; }
  }
  for (const b of document.querySelectorAll('[data-form]')) b.setAttribute('aria-pressed', b.dataset.form === form);
  for (const b of document.querySelectorAll('[data-genre]')) b.setAttribute('aria-pressed', b.dataset.genre === genre);
  $('swingrow').hidden = genre !== 'jazz'; $('driftrow').hidden = form !== 'wander';
  const t = first && +Q.get('tempo'); $('tempo').value = t >= 60 && t <= 200 ? t : BPM[genre]; $('bpm').textContent = $('tempo').value;
  first = false; links();
}
const picks = () => { const p = {}; for (const s of document.querySelectorAll('#parts select')) p[s.dataset.part] = +s.value; return p; };
function query(from) {
  const P = partsOf(genre, DEPS), pk = picks(), q = [];
  if (form === 'wander') { q.push(`from=${from}`, 'n=4'); if (!$('drift').checked) q.push('drift=0'); }
  if (genre === 'jazz' && +$('ride').value !== 2.5) q.push('ride=' + $('ride').value);
  for (const k in P) if (pk[k] !== P[k].kind) q.push(`${k}=${pk[k] < 0 ? 'off' : KINDS[pk[k]]}`);
  return q.length ? '?' + q.join('&') : '';
}
function links(from = 0) {
  const seed = +$('seed').value || 1, base = `/api/play/${form}/${genre}/${seed}`, q = query(from), amp = q ? '&' : '?';
  $('api-json').href = base + q; $('api-json').textContent = base + q;
  $('api-abc').href = base + q + amp + 'format=abc'; $('api-text').href = base + q + amp + 'format=text';
  const extra = query(0).replace(/^\?/, '').split('&').filter(x => x && !/^(from|n)=/.test(x));
  if (+$('tempo').value !== BPM[genre]) extra.unshift('tempo=' + $('tempo').value);
  history.replaceState(null, '', `?form=${form}&genre=${genre}&seed=${seed}` + extra.map(x => '&' + x).join(''));
}
for (const b of document.querySelectorAll('[data-form]')) b.onclick = () => { form = b.dataset.form; drawParts(true); if (ac) play(); };
for (const b of document.querySelectorAll('[data-genre]')) b.onclick = () => { genre = b.dataset.genre; drawParts(false); if (ac) play(); };
$('tempo').oninput = () => { $('bpm').textContent = $('tempo').value; links(); };
$('ride').oninput = () => { $('rv').textContent = (+$('ride').value).toFixed(2); links(); };
$('seed').onchange = () => links(); $('drift').onchange = () => links(); $('parts').onchange = () => links();

let ac, node, J = null, at0 = 0, spb = 0, queued = [], shown = 0, log = [];
async function boot() {
  ac = new AudioContext(); ac.resume(); // inside the tap, before any await, or phones stay muted
  await ac.audioWorklet.addModule('./rack/worklet.js');
  node = new AudioWorkletNode(ac, 'rack', { outputChannelCount: [2] }); node.connect(ac.destination);
  await new Promise(ok => { node.port.onmessage = ({ data }) => data.ready && ok(); node.port.postMessage({ wasm: rackB.buffer.slice(0) }); });
  node.port.onmessage = ({ data }) => heard(data);
}
// One phrase into worklet events: [sample, kind, hz, gain, length, part]
function phraseEvents(p) {
  const ev = p.notes.map(e => [at0 + Math.round(e.t * spb), e.kind, hz(e.m), e.g, Math.max(1, Math.round(e.d * spb)), e.part]);
  queued.push({ start: at0, end: at0 + Math.round(32 * spb), p, ev }); at0 += Math.round(32 * spb); return ev;
}
async function play() {
  if (!ac) await boot(); await ac.resume();
  const seed = +$('seed').value || 1, bpm = +$('tempo').value;
  spb = 60 / bpm * ac.sampleRate; at0 = Math.round(0.08 * ac.sampleRate); queued = []; shown = 0; log = [];
  J = jam({ form, genre, seed, drift: $('drift').checked, ride: genre === 'jazz' ? +$('ride').value : undefined, picks: picks() }, DEPS);
  const ev = phraseEvents(J.next()); if (form === 'wander') ev.push(...phraseEvents(J.next()));
  links();
  node.port.postMessage({ events: H.start({ name: `${form}-${genre}-seed${seed}`, form, genre, seed, bpm, sampleRate: ac.sampleRate, ride: genre === 'jazz' ? +$('ride').value : null,
    drift: form === 'wander' ? $('drift').checked : null, rack_sha: R.WASM_SHA, score_sha: S.WASM_SHA, wander_sha: WD.WASM_SHA,
    api: location.origin + $('api-json').getAttribute('href'), note: form === 'wander' ? 'grows a phrase at a time while it plays; download again for more' : undefined }, ev) });
}
// The worklet reports its clock about six times a second: queue more wander, and write what's sounding as text.
function heard(d) {
  if (!J) return;
  const now = d.at * ac.sampleRate;
  if (form === 'wander' && now > at0 - 8 * ac.sampleRate) { const p = J.next(); if (p) node.port.postMessage({ more: H.more(phraseEvents(p)) }); }
  const cur = queued.find(q => now >= q.start && now < q.end);
  if (cur) {
    const p = cur.p, bar = Math.min(8, 1 + Math.floor((now - cur.start) / spb / 4));
    const ch = p.chords ? p.chords.split(' | ')[bar - 1] : null;
    $('now').innerHTML = `${form === 'wander' ? `phrase ${p.index}` : 'track'} · <b>${p.keyName}</b> · bar ${bar} of 8${ch ? ` · chord <b>${ch}</b>` : ''}`;
    if (form === 'wander') $('inst').textContent = Object.entries(p.picks).map(([k, v]) => `${k} ${v}`).join(' · ');
  }
  // notes whose start has passed since the last report, as names; melody first, drums counted
