const { instance } = await WebAssembly.instantiate(bytes);
const W = instance.exports;

const SCALE = [0, 2, 4, 5, 7, 9, 11];
const midi = d => 60 + 12 * Math.floor(d / 7) + SCALE[((d % 7) + 7) % 7];
const NAMES = 'CDEFGAB';
