export async function main(runs = 20, T = 1500) {
  const M = buildMaze(1);
  console.log(`maze seed 1: ${M.open} open squares, solution path ${M.len} steps, food ${M.food} squares (p = ${M.p.toFixed(4)}), h = 0.9, ${T} steps, seeds 1000r+7`);
